    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx > 0)
        {
            await MoveTask(task, columns[idx - 1].Status);
        }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx >= 0 && idx < columns.Length - 1)
        {
            await MoveTask(task, columns[idx + 1].Status);
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var i = allTasks.FindIndex(t => t.Id == task.Id);
            if (i >= 0)
            {
                allTasks[i] = task with { Status = newStatus };
