@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    private readonly record struct ColumnDef(string Name, string Status);

    private static readonly ColumnDef[] columns =
    [
        new("To Do", "To Do"),
        new("In Progress", "In Progress"),
        new("Done", "Done")
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
    {
        var filtered = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveLeft(TaskItem task)
    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx > 0)
        {
            await MoveTask(task, columns[idx - 1].Status);
        }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx >= 0 && idx < columns.Length - 1)
        {
            await MoveTask(task, columns[idx + 1].Status);
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var i = allTasks.FindIndex(t => t.Id == task.Id);
            if (i >= 0)
            {
                allTasks[i] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleTaskCreated(TaskItem placeholder)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                placeholder.Title, placeholder.Assignee, placeholder.Priority, placeholder.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

