@namespace sv_36d7661f6faf466bbf8ad248c21f371f.Components.Pages.Board

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@page "/board"
@namespace sv_36d7661f6faf466bbf8ad248c21f371f.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="container-fluid py-3">
    <h3 class="mb-3">Kanban Board</h3>

    @if (loading)
    {
        <div class="d-flex justify-content-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger" role="alert">
            <strong>Error:</strong> @errorMessage
            <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStatsBar Tasks="allTasks" />
        <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

        <div class="row g-3">
            @for (var i = 0; i < columns.Length; i++)
            {
                var col = columns[i];
                var idx = i;
                <KanbanColumn ColumnName="@col.Name"
                              Status="@col.Status"
                              Tasks="GetColumnTasks(col.Status)"
                              IsFirst="(idx == 0)"
                              IsLast="(idx == columns.Length - 1)"
                              OnMoveLeft="HandleMoveLeft"
                              OnMoveRight="HandleMoveRight"
                              OnTaskCreated="HandleTaskCreated" />
            }
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    private readonly record struct ColumnDef(string Name, string Status);

    private static readonly ColumnDef[] columns =
    [
        new("To Do", "To Do"),
        new("In Progress", "In Progress"),
        new("Done", "Done")
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
    {
        var filtered = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveLeft(TaskItem task)
    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx > 0)
        {
            await MoveTask(task, columns[idx - 1].Status);
        }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var idx = Array.FindIndex(columns, c => c.Status == task.Status);
        if (idx >= 0 && idx < columns.Length - 1)
        {
            await MoveTask(task, columns[idx + 1].Status);
        }
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var i = allTasks.FindIndex(t => t.Id == task.Id);
            if (i >= 0)
            {
                allTasks[i] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleTaskCreated(TaskItem placeholder)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                placeholder.Title, placeholder.Assignee, placeholder.Priority, placeholder.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

